sp_widget.client_script:
api.controller = function() {
    var c = this;

    c.getBarWidth = function(count, max) {
        if (!max || max === 0) return '0%';
        return Math.round((count / max) * 100) + '%';
    };

    c.getStatusClass = function(status) {
        if (!status) return 'label-default';
        var s = status.toLowerCase();
        if (s === 'approved') return 'label-success';
        if (s === 'in_progress' || s === 'in progress') return 'label-warning';
        if (s === 'rejected') return 'label-danger';
        if (s === 'submitted') return 'label-info';
        return 'label-default';
    };

    c.getPriorityClass = function(priority) {
        if (!priority) return 'label-default';
        var p = priority.toLowerCase();
        if (p === 'critical') return 'label-danger';
        if (p === 'high') return 'label-warning';
        if (p === 'medium') return 'label-info';
        return 'label-default';
    };
};

sp_widget.css:
/* KPI Cards Row */
.sp-kpi-row {
    display: flex;
    gap: 16px;
    margin-bottom: 28px;
    flex-wrap: wrap;
}
.sp-kpi-card {
    flex: 1;
    min-width: 160px;
    background: #ffffff;
    border: 1px solid #e8edf2;
    border-radius: 8px;
    padding: 20px;
    display: flex;
    align-items: center;
    gap: 14px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
    transition: box-shadow 0.2s ease;
}
.sp-kpi-card:hover {
    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.08);
}
.sp-kpi-icon-wrap {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}
.sp-kpi-icon-wrap .glyphicon {
    font-size: 18px;
}
.sp-kpi-value {
    font-size: 24px;
    font-weight: 700;
    color: #1a2b3c;
    line-height: 1;
}
.sp-kpi-label {
    font-size: 12px;
    color: #6b7b8c;
    margin-top: 4px;
    font-weight: 500;
}

/* KPI Color Variants */
.sp-kpi-total .sp-kpi-icon-wrap {
    background: #eff6ff;
}
.sp-kpi-total .sp-kpi-icon-wrap .glyphicon {
    color: #3b82f6;
}
.sp-kpi-submitted .sp-kpi-icon-wrap {
    background: #ecfeff;
}
.sp-kpi-submitted .sp-kpi-icon-wrap .glyphicon {
    color: #0891b2;
}
.sp-kpi-progress .sp-kpi-icon-wrap {
    background: #fffbeb;
}
.sp-kpi-progress .sp-kpi-icon-wrap .glyphicon {
    color: #d97706;
}
.sp-kpi-approved .sp-kpi-icon-wrap {
    background: #ecfdf5;
}
.sp-kpi-approved .sp-kpi-icon-wrap .glyphicon {
    color: #059669;
}
.sp-kpi-rejected .sp-kpi-icon-wrap {
    background: #fef2f2;
}
.sp-kpi-rejected .sp-kpi-icon-wrap .glyphicon {
    color: #dc2626;
}

/* Chart Panels */
.sp-chart-panel {
    border: 1px solid #e8edf2;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
    margin-bottom: 20px;
}
.sp-chart-panel .panel-heading {
    background: #f8fafb;
    border-bottom: 1px solid #e8edf2;
}

/* Bar Chart Rows */
.sp-bar-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
}
.sp-bar-label {
    font-size: 13px;
    color: #3a4b5c;
    min-width: 110px;
    flex-shrink: 0;
}
.sp-bar-track {
    flex: 1;
    height: 22px;
    background: #f1f5f9;
    border-radius: 4px;
    overflow: hidden;
}
.sp-bar-fill {
    height: 100%;
    border-radius: 4px;
    transition: width 0.4s ease;
    min-width: 2px;
}
.sp-bar-info {
    background: linear-gradient(90deg, #06b6d4, #0891b2);
}
.sp-bar-warning {
    background: linear-gradient(90deg, #f59e0b, #d97706);
}
.sp-bar-success {
    background: linear-gradient(90deg, #10b981, #059669);
}
.sp-bar-primary {
    background: linear-gradient(90deg, #0d8a8f, #0a6e7a);
}
.sp-bar-count {
    font-size: 13px;
    font-weight: 700;
    color: #3a4b5c;
    min-width: 32px;
    text-align: right;
}

/* Recent Table */
.sp-flush-body {
    padding: 0;
}
.sp-recent-table {
    margin-bottom: 0;
}
.sp-recent-table thead th {
    background: #f8fafb;
    font-size: 12px;
    font-weight: 600;
    color: #5a6b7c;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    border-bottom: 2px solid #e8edf2;
    padding: 10px 14px;
}
.sp-recent-table tbody td {
    font-size: 13px;
    padding: 10px 14px;
    vertical-align: middle;
}

/* Urgent Panel */
.sp-urgent-panel {
    border-color: #fecaca;
}
.sp-urgent-heading {
    background: #fef2f2 !important;
    border-bottom-color: #fecaca !important;
}
.sp-urgent-heading .panel-title {
    color: #dc2626;
}

@media (max-width: 991px) {
    .sp-kpi-row {
        flex-wrap: wrap;
    }
    .sp-kpi-card {
        min-width: calc(50% - 16px);
    }
}
@media (max-width: 575px) {
    .sp-kpi-card {
        min-width: 100%;
    }
}

sp_widget.script:
(function() {
    var table = 'x_839216_public_0_health_service_request_v1';
    data.statusDist = [];
    data.priorityDist = [];
    data.typeDist = [];
    data.groupDist = [];
    data.recentRequests = [];
    data.highPriorityRequests = [];
    data.stats = {total: 0, submitted: 0, in_progress: 0, approved: 0, rejected: 0};

    var statusMap = {};
    var priorityMap = {};
    var typeMap = {};
    var groupMap = {};

    var gr = new GlideRecord(table);
    gr.setLimit(500);
    gr.query();
    while (gr.next()) {
        var status = gr.getDisplayValue('u_status') + '';
        var priority = gr.getDisplayValue('u_priority') + '';
        var reqType = gr.getDisplayValue('u_request_type') + '';
        var group = gr.getDisplayValue('assignment_group') + '';

        data.stats.total++;
        var statusLower = status.toLowerCase();
        if (statusLower === 'submitted') data.stats.submitted++;
        else if (statusLower === 'in_progress' || statusLower === 'in progress') data.stats.in_progress++;
        else if (statusLower === 'approved') data.stats.approved++;
        else if (statusLower === 'rejected') data.stats.rejected++;

        statusMap[status] = (statusMap[status] || 0) + 1;
        priorityMap[priority] = (priorityMap[priority] || 0) + 1;
        typeMap[reqType] = (typeMap[reqType] || 0) + 1;
        if (group) {
            groupMap[group] = (groupMap[group] || 0) + 1;
        }
    }

    for (var s in statusMap) {
        data.statusDist.push({label: s, count: statusMap[s]});
    }
    for (var p in priorityMap) {
        data.priorityDist.push({label: p, count: priorityMap[p]});
    }
    for (var t in typeMap) {
        data.typeDist.push({label: t, count: typeMap[t]});
    }
    for (var g in groupMap) {
        data.groupDist.push({label: g, count: groupMap[g]});
    }

    data.maxStatus = 0;
    data.maxPriority = 0;
    data.maxType = 0;
    data.maxGroup = 0;
    for (var i = 0; i < data.statusDist.length; i++) {
        if (data.statusDist[i].count > data.maxStatus) data.maxStatus = data.statusDist[i].count;
    }
    for (var j = 0; j < data.priorityDist.length; j++) {
        if (data.priorityDist[j].count > data.maxPriority) data.maxPriority = data.priorityDist[j].count;
    }
    for (var k = 0; k < data.typeDist.length; k++) {
        if (data.typeDist[k].count > data.maxType) data.maxType = data.typeDist[k].count;
    }
    for (var l = 0; l < data.groupDist.length; l++) {
        if (data.groupDist[l].count > data.maxGroup) data.maxGroup = data.groupDist[l].count;
    }

    // Recent Requests (last 10)
    var recentGr = new GlideRecord(table);
    recentGr.orderByDesc('sys_created_on');
    recentGr.setLimit(10);
    recentGr.query();
    while (recentGr.next()) {
        data.recentRequests.push({
            sys_id: recentGr.getUniqueValue(),
            number: recentGr.getValue('number') + '',
            u_request_type: recentGr.getDisplayValue('u_request_type') + '',
            u_priority: recentGr.getDisplayValue('u_priority') + '',
            u_status: recentGr.getDisplayValue('u_status') + '',
            sys_created_on: recentGr.getDisplayValue('sys_created_on') + ''
        });
    }

    // High/Critical Priority Requests (open only)
    var urgentGr = new GlideRecord(table);
    urgentGr.addEncodedQuery('u_priorityINhigh,critical^u_statusINsubmitted,in_progress');
    urgentGr.orderByDesc('sys_created_on');
    urgentGr.setLimit(10);
    urgentGr.query();
    while (urgentGr.next()) {
        data.highPriorityRequests.push({
            sys_id: urgentGr.getUniqueValue(),
            number: urgentGr.getValue('number') + '',
            u_request_type: urgentGr.getDisplayValue('u_request_type') + '',
            u_priority: urgentGr.getDisplayValue('u_priority') + '',
            u_status: urgentGr.getDisplayValue('u_status') + '',
            u_citizen_name: urgentGr.getValue('u_citizen_name') + ''
        });
    }
})();
